   330  static inline void *
   331  hb_bsearch (const void *key, const void *base,
   332              size_t nmemb, size_t size,
   333              int (*compar)(const void *_key, const void *_item))
   334  {
   335    int min = 0, max = (int) nmemb - 1;
   336    while (min <= max)
   337    {
   338      int mid = (min + max) / 2;
   339      const void *p = (const void *) (((const char *) base) + (mid * size));
   340      int c = compar (key, p);
   341      if (c < 0)
   342        max = mid - 1;
   343      else if (c > 0)
   344        min = mid + 1;
   345      else
   346        return (void *) p;
   347    }
   348    return nullptr;
   349  }
   350
   351  static inline void *
   352  hb_bsearch_r (const void *key, const void *base,
   353                size_t nmemb, size_t size,
   354                int (*compar)(const void *_key, const void *_item, void *_arg),
   355                void *arg)
   356  {
   357    int min = 0, max = (int) nmemb - 1;
   358    while (min <= max)
   359    {
   360      int mid = ((unsigned int) min + (unsigned int) max) / 2;
   361      const void *p = (const void *) (((const char *) base) + (mid * size));
   362      int c = compar (key, p, arg);
   363      if (c < 0)
   364        max = mid - 1;
   365      else if (c > 0)
   366        min = mid + 1;
   367      else
   368        return (void *) p;
   369    }
   370    return nullptr;
   371  }
